window.kbPageData["views/entry/k-f1d0d8ca54f728eb"] = {"key":"entry/k-f1d0d8ca54f728eb","state":{"route":"entry/k-f1d0d8ca54f728eb"},"node":{"id":"k-f1d0d8ca54f728eb","mode":"k","title":"碳达峰碳中和","type":"概念与词义","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["生态环境"],"来源主题":["生态环境与能源"],"资料类别":["非时政"]},"directorySummary":"2.碳达峰碳中和\n力争 2030 年前二氧化碳排放达到峰值，努力争取 2060 年前实现碳中和目标。\n——《2020 年 9 月 22 日习近平总书记在第 75 届联合国大会上的讲话》\n实现碳达峰碳中和是一场广泛而深刻的经济社会系统性变革。立足我国能源资源禀赋，\n坚持先立后破，有计划分步骤实施碳达峰…","sources":[{"id":"e44bdc8ad38691cf","label":"碳达峰碳中和","topic":"生态环境与能源","category":"非时政","text":"2.碳达峰碳中和\n力争 2030 年前二氧化碳排放达到峰值，努力争取 2060 年前实现碳中和目标。\n——《2020 年 9 月 22 日习近平总书记在第 75 届联合国大会上的讲话》\n实现碳达峰碳中和是一场广泛而深刻的经济社会系统性变革。立足我国能源资源禀赋，\n坚持先立后破，有计划分步骤实施碳达峰行动。完善能源消耗总量和强度调控，重点控制化\n石能源消费，逐步转向碳排放总量和强度“双控”制度。\n——《党的二十大报告》\n习近平宣布中国新一轮国家自主贡献：到 2035 年，中国全经济范围温室气体净排放量\n比峰值下降 7%-10%，力争做得更好。非化石能源消费占能源消费总量的比重达到 30%以上，\n风电和太阳能发电总装机容量达到 2020 年的 6 倍以上、力争达到 36 亿千瓦，森林蓄积\n量达到 240 亿立方米以上，新能源汽车成为新销售车辆的主流，全国碳排放权交易市场覆\n盖主要高排放行业，气候适应型社会基本建成。\n——《2025 年 9 月 24 日习近平在联合国气候变化峰会发表视频致辞》","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-f1d0d8ca54f728eb":[]}};
